package com.guocheng.mediapocket;
import android.app.*;import android.content.SharedPreferences;import android.widget.Toast;import org.json.JSONObject;import java.io.File;import java.util.*;
/** 播放页搜索射手和 OpenSubtitles，下载后落盘并载入当前这一条字幕。 */
final class OnlineSubtitleController {
 private OnlineSubtitleController(){}
 static SharedPreferences prefs(Activity a){return a.getSharedPreferences("data",0);}
 static String assrt(SharedPreferences p){return p.getString("subtitle.assrtToken","");}
 static String openKey(SharedPreferences p){return p.getString("subtitle.opensubtitlesKey","");}
 static void open(Activity a){String why=OnlineSubtitleRules.missing(assrt(prefs(a)),openKey(prefs(a)));if(why!=null){new AlertDialog.Builder(a).setTitle("在线字幕").setMessage(why).setPositiveButton("知道了",null).show();return;}String title=PlayerOverlay.name(a);JSONObject meta=PlayerOverlay.meta(a);String query=MediaMatchRules.clean(meta.optString("fusion.title",title));if(query.isEmpty())query=title;if(query.isEmpty()){Toast.makeText(a,"还不知道片名，无法搜索字幕",Toast.LENGTH_SHORT).show();return;}final String word=query;final String token=assrt(prefs(a)),key=openKey(prefs(a));final ProgressDialog wait=ProgressDialog.show(a,"搜索字幕","正在查询射手和 OpenSubtitles…",true,true);final boolean[] cancel={false};wait.setOnCancelListener(d->cancel[0]=true);OnlineSubtitleSearch.IO.execute(()->{ArrayList<OnlineSubtitleRules.Hit> hits=new ArrayList<>();StringBuilder note=new StringBuilder();if(OnlineSubtitleRules.assrtReady(token))try{hits.addAll(OnlineSubtitleRules.assrt(OnlineSubtitleClient.assrt(OnlineSubtitleRules.assrtSearch(token,word))));}catch(Exception e){note.append("射手：").append(e.getMessage()==null?"查询失败":e.getMessage()).append('\n');}if(OnlineSubtitleRules.openReady(key))try{hits.addAll(OnlineSubtitleRules.opensubtitles(OnlineSubtitleClient.opensubtitles(OnlineSubtitleRules.openSearch(word),key)));}catch(Exception e){note.append("OpenSubtitles：").append(e.getMessage()==null?"查询失败":e.getMessage()).append('\n');}final String problem=note.toString();a.runOnUiThread(()->{if(a.isFinishing()||cancel[0])return;if(wait.isShowing())wait.dismiss();if(hits.isEmpty()){new AlertDialog.Builder(a).setTitle("在线字幕").setMessage(problem.isEmpty()?"没有找到字幕":problem).setPositiveButton("确定",null).show();return;}String[] labels=new String[hits.size()];for(int i=0;i<hits.size();i++)labels[i]=hits.get(i).label();new AlertDialog.Builder(a).setTitle("选择字幕").setItems(labels,(d,i)->download(a,hits.get(i),word)).setNegativeButton("取消",null).show();});});}
 static void download(Activity a,OnlineSubtitleRules.Hit hit,String title){final String token=assrt(prefs(a)),key=openKey(prefs(a));final ProgressDialog wait=ProgressDialog.show(a,"下载字幕",hit.label(),true,true);OnlineSubtitleSearch.IO.execute(()->{try{String url=hit.url;if("assrt".equals(hit.source))url=OnlineSubtitleRules.assrtFile(OnlineSubtitleClient.assrt(OnlineSubtitleRules.assrtDetail(token,hit.id)));else url=OnlineSubtitleRules.openLink(OnlineSubtitleClient.openDownload(key,hit.fileId));if(url.isEmpty())throw new java.io.IOException("没有可下载的字幕地址");byte[] bytes=OnlineSubtitleRules.unwrap(OnlineSubtitleClient.bytes(url));String filename=OnlineSubtitleRules.file(hit.name,bytes);File saved=ExternalSubtitleStore.save(a,title,filename,bytes);String path=saved.getAbsolutePath();String id=PlayerOverlay.id(a);ExternalSubtitleStore.remember(prefs(a),id,path,OnlineSubtitleRules.choice(hit.source,hit.id,hit.fileId));a.runOnUiThread(()->{if(wait.isShowing())wait.dismiss();if(a.isFinishing())return;SourceSubtitleLoader.showLocal(a,bytes,hit.label(),path);});}catch(Exception e){a.runOnUiThread(()->{if(wait.isShowing())wait.dismiss();if(!a.isFinishing())OnlineSubtitleSearch.message(a,"字幕下载失败："+(e.getMessage()==null?e.getClass().getSimpleName():e.getMessage()));});}});}
}
